import 'dart:convert';
import 'package:flutter/material.dart';

/// Approved PRIVATE DRIVE logo №1 (Toyota-free). Offline-only image.
/// Stored as a compact WebP for reproducible Android builds.
const privateDriveLogoBase64 = '';

class PrivateDriveBrandLogo extends StatelessWidget {
  const PrivateDriveBrandLogo({super.key, this.size = 176});
  final double size;

  @override
  Widget build(BuildContext context) => Image.memory(
    base64Decode(privateDriveLogoBase64),
    key: const Key('private-drive-brand-logo'),
    width: size,
    height: size,
    filterQuality: FilterQuality.high,
    fit: BoxFit.contain,
    gaplessPlayback: true,
  );
}
